        printf("Usage: ./argv_index [index]\n");
        return 1;
    }

    int index = atoi(argv[1]); // Convert the input index to an integer

    if (index <= 0 || index > argc) { // Check for valid index
        printf("Index should be between 1 and the number of arguments.\n");
        return 1;
    }

