[' Here's a simple C program that does what you've described. I've used `stdarg.h` for handling variable arguments, as there can be different numbers of command-line arguments.

```c
#include <stdio.h>
#include <stdarg.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    int offset = 1000;
    int value;

    if (argc != 2) {
        printf("Usage: %s <value>\n", argv[0]);
        return 1;
    }

    va_list args;
    va_start(args, argc);
    value = atoi(va_arg(args, char *));
    va_end(args);

    printf("Original value: %d\n", value);
    printf("Value with offset added: %d\n", value + offset);

    return 0;
}
```

To compile this program, save it in a file called `add_offset.c` and run the following command:

