[' Here's a simple C code example that does what you asked for. This code reads the content of a file into a buffer, calculates its checksum (using XOR operation), saves the number of bytes read and the checksum to another file.

```c
#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <unistd.h>

int main(int argc, char *argv[]) {
    if (argc != 3) {
        printf("Usage: %s input_file output_file\n", argv[0]);
        return 1;
    }

    FILE *input = fopen(argv[1], "rb");
    if (!input) {
        perror("Error opening file");
        return 1;
    }

    struct stat st;
    if (stat(argv[1], &st) == -1) {
        perror("Error getting file size");
        fclose(input);
        return 1;
    }

    unsigned char *buffer = malloc(st.st_size);
    if (!buffer) {
        perror("Error allocating memory for buffer");
        fclose(input);
        return 1;
    }

    size_t bytesRead = fread(buffer, sizeof(unsigned char), st.st_size, input);
    if (bytesRead != st.st_size) {
        perror("Error reading file");
        free(buffer);
        fclose(input);
        return 1;
    }

    FILE *output = fopen(argv[2], "w");
    if (!output) {
        perror("Error opening output file");
        free(buffer);
        fclose(input);
        return 1;
    }

    unsigned int checksum = 0;
    for (size_t i = 0; i < bytesRead; ++i) {
        checksum ^= buffer[i];
    }

    fprintf(output, "Bytes read: %zu\nChecksum: %u\n", bytesRead, checksum);

    free(buffer);
    fclose(input);
    fclose(output);

    return 0;
}
```

To use this code, compile it with gcc (e.g., `gcc checksum.c -o checksum`) and then run the resulting executable (`./checksum input_file output_file`). Make sure to replace `input_file` and `output_file` with your desired file paths.']

[' Here's the C code for your request. This code uses a simple XOR operation for the checksum calculation, which is suitable for this task. I've also included error handling for opening files.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc != 3) { // Check input arguments
        printf("Usage: %s <input_file> <output_file>\n", argv[0]);
        return -1;
    }

    FILE *inputFile = fopen(argv[1], "rb"); // Open the input file
    if (!inputFile) {
        perror("Error opening input file");
        return -2;
    }

    FILE *outputFile = fopen(argv[2], "w+"); // Open the output file
    if (!outputFile) {
        perror("Error opening output file");
        fclose(inputFile);
        return -3;
    }

    unsigned char buffer[256]; // Create a buffer for reading data from the input file
    size_t numBytesRead = 0; // Variable to store the number of bytes read
    unsigned int checksum = 0; // Variable to store the checksum

    while ((numBytesRead = fread(buffer, sizeof(unsigned char), sizeof(buffer), inputFile)) > 0) {
        for (size_t i = 0; i < numBytesRead; ++i) {
            checksum ^= buffer[i]; // XOR the checksum with each byte in the buffer
        }
    }

    if (feof(inputFile)) { // Check if we've reached the end of the input file
        printf("Buffer is empty.\n");
    } else if (!ferror(inputFile)) { // If there was no error reading from the input file
        fprintf(outputFile, "Number of bytes read: %lu\n", numBytesRead);
        fprintf(outputFile, "Checksum: 0x%x\n", checksum);
    } else { // If there was an error reading from the input file
        perror("Error reading from input file");
    }

    fclose(inputFile); // Close the input file
    fclose(outputFile); // Close the output file

    return 0;
}
```

Save this code in a file called `checksum_file.c`, and compile it using gcc:

```sh
gcc checksum_file.c -o checksum_file
```

You can then run the compiled binary with the desired input and output files:

```sh
./checksum_file input.bin output.txt
```']

