[' Here's a C code snippet that demonstrates how to execute the `getent passwd <username>` command using both `system()` and `popen()` functions, and store the output in a file pointer `output`.

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: %s <username>\n", argv[0]);
        return -1;
    }

    FILE *output = fopen("output", "w");
    if (!output) {
        perror("fopen");
        return -2;
    }

    // Using system() function
    int status;
    char command[128];
    snprintf(command, sizeof(command), "getent passwd %s > output", argv[1]);
    system(command);

    // Using popen() function
    FILE *pipe = popen(command, "r");
    if (!pipe) {
        perror("popen");
        fclose(output);
        return -3;
    }

    char buffer[128];
    size_t n;
    while ((n = fread(buffer, sizeof(char), sizeof(buffer)-1, pipe)) > 0) {
        buffer[n] = '\0';
        fputs(buffer, output);
    }

    if (pclose(pipe) == -1) {
        perror("pclose");
    }
    fclose(output);

    return 0;
}
```

Just build the code and provide a username as an argument to run it. This code will execute the command `getent passwd <username>` using both system() and popen() functions, and store the output in a file named "output".']

[' Here is a simple C program that fulfills your requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>

void executeCommand(char* command) {
    pid_t pid;
    int status;
    int pipefd[2];
    char *args[] = {"sh", "-c", command, NULL};

    if (pipe(pipefd) < 0) {
        perror("Error creating pipe");
        exit(EXIT_FAILURE);
    }

    pid = fork();

    if (pid == -1) {
        perror("Error forking process");
        exit(EXIT_FAILURE);
    }

    if (!pid) { // Child process
        close(pipefd[0]);
        dup2(pipefd[1], STDOUT_FILENO);
        close(pipefd[1]);

        execvp("sh", args);
        perror("Error executing command");
        exit(EXIT_FAILURE);
    }

    waitpid(pid, &status, 0);

    close(pipefd[1]);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s username\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char command[] = "cat /etc/passwd | grep ";
    char cmdline[sizeof(command) + strlen(argv[1]) + 2]; // for the space and null terminator
    strcpy(cmdline, command);
    strcat(cmdline, argv[1]);
    strcat(cmdline, " ");
    strcat(cmdline, "/etc/passwd");

    executeCommand(cmdline);

    return EXIT_SUCCESS;
}
```

This program takes a single command line argument (the username) and constructs the desired command as `cat /etc/passwd | grep [username]`. It uses the `fork()` system call to create a child process that executes the constructed command. The pipe is used to capture the output of the `cat` command and pass it as input for the `grep` command.

