#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>

int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: %s <username>\n", argv[0]);
        return 1;
    }

    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return 1;
    } else if (pid == 0) { // Child process
        execlp("id", "id", argv[1], NULL);
        perror("execlp");
        return 1;
    } else {              // Parent process
        int status;
        waitpid(pid, &status, 0);
        printf("Exit status: %d\n", WEXITSTATUS(status));
        return WEXITSTATUS(status);
    }
}
```

This code forks a new process, and in the child process, it executes the `id` command with the provided username as an argument using `execlp`. In the parent process, it waits for the child to finish executing the command and then prints the exit status of the command. The exit status is obtained by using `WEXITSTATUS(status)`. If there's any error during the execution, appropriate error messages will be printed using `perror()`.

You should compile this code with a C compiler like gcc:

