[' To achieve this, we will use the `popen()` and `printf()` functions from the C standard library. Here's an example code demonstrating how to create a function called `execute_command` that takes a formatted string as its argument and executes the `ls` command using the provided format:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

FILE *execute_command(const char *format, ...) {
    FILE *pipe;
    char command[128];
    va_list args;
    int i = 0;

    va_start(args, format);
    while (format[i] != '\0') {
        if (format[i] == '%') {
            i++;
            switch (format[i]) {
                case 's':
                    strcat(command, va_arg(args, char *));
                    break;
                // Add more placeholders as needed.
                default:
                    fprintf(stderr, "Invalid placeholder: %c\n", format[i]);
                    exit(1);
            }
        } else {
            command[i] = format[i];
        }
        i++;
    }
    command[sizeof(command) - 1] = '\0'; // Ensure null-terminated.

    pipe = popen(command, "r");
    if (pipe == NULL) {
        perror("popen() error");
        exit(1);
    }

    return pipe;
}

void print_ls_result(FILE *stream) {
    char c;
    while ((c = fgetc(stream)) != EOF) {
        putchar(c);
    }
}

int main() {
    FILE *stream;
    const char *format = "ls %s";
    char directory[128];

    printf("Enter the directory to list: ");
    scanf("%s", directory);

    stream = execute_command(format, directory);
    print_ls_result(stream);

    pclose(stream);

    return 0;
}
```

This code defines a function called `execute_command` that takes a formatted string as its argument and executes the `ls` command using the provided format. The `print_ls_result` function is used to display the results of the executed command. In this example, the user is asked to enter a directory name, which will be passed to the `execute_command` function, and then the results are displayed on the console.']

