```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>

void print_trimmed(int argc, char *argv[]) {
    if (argc > 1) {
        int len = strlen(argv[1]);
        for (int i = len - 1; i >= 0 && isspace(argv[1][i]); --i) {
            len = i + 1;
        }
        printf("%.*s\n", len, argv[1]);
    }
}

int main(int argc, char *argv[]) {
