[' Here's a simple C code example using an embedded web server library like POCO or Boost.Asio for this task. I'll provide you with a basic Boost.Asio example below. Please note that this example assumes you have a working development environment set up for C++ with Boost.Asio installed.

```cpp
#include <boost/asio.hpp>
#include <iostream>
#include <string>

namespace asio = boost::asio;
using boost::asio::ip::tcp;

std::string username;
char outputbuf[1024];

void http_hello_page(asio::yield_context yield, tcp::socket& socket) {
    // Read the request body (username) from the socket
    asio::streambuf request_buffer;
    asio::read_until(socket, request_buffer, "\r\n\r\n");
    std::istream is(&request_buffer);
    std::string line;
    while (std::getline(is, line)) {
        if (line.substr(0, 9) == "Host: localhost") // Assuming the host is localhost here
            continue;
        if (line.substr(0, 6) == "User: ") {
            username = line.substr(6);
            break;
        }
    }

    // Construct the response body
    snprintf(outputbuf, sizeof(outputbuf),
             "<html>\n"
             "<head><title>Hello %s</title></head>\n"
             "<body>\n"
             "<h1>Hello, %s!</h1>\n"
             "</body>\n"
             "</html>", username.c_str(), username.c_str());

    // Write the response body to the socket
    asio::streambuf response_buffer;
    asio::write(socket, asio::buffer(outputbuf), yield);

    // Close the socket
    socket.shutdown(tcp::socket::shutdown_both, yield);
}

int main() {
    try {
        asio::io_context io_context;

        tcp::acceptor acceptor(io_context, tcp::endpoint(tcp::v4(), 8080)); // Bind to port 8080

        for (;;) {
            tcp::socket socket(io_context);
            acceptor.accept(socket);

            http_hello_page(io_context.get_executor().wrap(std::move(socket)), socket);
        }
    } catch (std::exception& e) {
        std::cerr << "Exception: " << e.what() << "\n";
        return 1;
    }
}
```

This code creates a simple web server that listens on port 8080 and responds with an HTML page containing the given username when it receives a request to /hello. The user's input is read from the request body, which in this example assumes a line starting with "User: ".']

