[" Here's a Python code implementation that satisfies your requirements using a decorator and Flask web framework:

```python
from flask import Flask, escape
import functools

app = Flask(__name__)

def url_mapping(url):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            username = kwargs['username'] if 'username' in kwargs else ''
            app.add_url_rule(url.format(username=escape(username)), view_func=func, methods=['GET'])
            return func(*args, **kwargs)
        return wrapper
    return decorator

@url_mapping('/hello/{username}')
def hello(username):
    if username:
        return 'Hello {}'.format(username)
    else:
        return 'Hello'

if __name__ == '__main__':
    app.run(debug=True)
```

